-- 입력 데이터 전체 (SQLite)
-- CREATE TABLE orders(refund INTEGER);
SELECT SUM(COALESCE(refund, 0)), COALESCE(SUM(refund), 0)
FROM orders;

-- 입력 데이터 전체 (SQLite)
-- CREATE TABLE orders(refund INTEGER);
-- INSERT INTO orders VALUES(NULL),(NULL);
SELECT COUNT(*), COUNT(refund), SUM(COALESCE(refund, 0))
FROM orders;

-- 입력 데이터 전체 (SQLite)
-- CREATE TABLE orders(refund INTEGER);
-- INSERT INTO orders VALUES(2),(NULL),(4);
SELECT AVG(refund), AVG(COALESCE(refund, 0))
FROM orders;

-- 입력 데이터 전체 (SQLite)
-- CREATE TABLE orders(refund INTEGER);
-- INSERT INTO orders VALUES(2),(2),(NULL),(3);
SELECT SUM(refund), SUM(DISTINCT refund)
FROM orders;

-- 입력 데이터 전체 (SQLite)
-- CREATE TABLE customers(id INTEGER);
-- INSERT INTO customers VALUES(1),(2),(3);
-- CREATE TABLE orders(id INTEGER, customer_id INTEGER, status TEXT);
-- INSERT INTO orders VALUES(10,1,'done'),(11,2,'open');
SELECT COUNT(*)
FROM customers AS c
LEFT JOIN orders AS o
    ON c.id = o.customer_id AND o.status = 'done'
WHERE o.id IS NULL;
